import{_ as t,o as e,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"框架与平台选型","description":"按模型接入、Agent、工作流、评测、观测和托管责任分层比较自建、LangChain/LangGraph 与平台方案。","frontmatter":{"title":"框架与平台选型","description":"按模型接入、Agent、工作流、评测、观测和托管责任分层比较自建、LangChain/LangGraph 与平台方案。","verified_at":"2026-07-31","source":["https://docs.langchain.com/oss/python/langchain/overview","https://docs.langchain.com/oss/python/langgraph/overview","https://docs.llamaindex.ai/","https://opentelemetry.io/docs/"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/technology-product-design/framework-platform-selection.md","filePath":"py-agent/architecture/technology-product-design/framework-platform-selection.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/technology-product-design/framework-platform-selection.md"};function i(o,a,h,s,d,p){return e(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="框架与平台选型" tabindex="-1">框架与平台选型 <a class="header-anchor" href="#框架与平台选型" aria-label="Permalink to &quot;框架与平台选型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>“选哪个 Agent 框架”把多个决策压成了一句。模型 SDK、组件抽象、持久工作流、RAG、评测、观测、部署平台和托管控制面可以独立选择。先确定系统需要哪一层能力，再判断框架的抽象是否匹配，而不是比较功能清单长度。</p><p>本章比较框架承担哪些架构责任，不重复 API 教程。LangChain 的 Agent 入口见<a href="/py-agent/agent/agent-runtime/create-agent"><code>create_agent()</code></a>，LangGraph 的 State、Node 和 Edge 见<a href="/py-agent/workflow/langgraph-core/langgraph-overview-minimal-graph">LangGraph 概览与最小图</a>。</p><h2 id="_1-选择层级" tabindex="-1">1. 选择层级 <a class="header-anchor" href="#_1-选择层级" aria-label="Permalink to &quot;1. 选择层级&quot;">​</a></h2><h3 id="_1-1-模型访问层" tabindex="-1">1.1 模型访问层 <a class="header-anchor" href="#_1-1-模型访问层" aria-label="Permalink to &quot;1.1 模型访问层&quot;">​</a></h3><p>供应商 SDK 或统一模型适配器，负责消息、工具、流式、结构化输出、错误和用量。</p><h3 id="_1-2-agent-组件层" tabindex="-1">1.2 Agent 组件层 <a class="header-anchor" href="#_1-2-agent-组件层" aria-label="Permalink to &quot;1.2 Agent 组件层&quot;">​</a></h3><p>Prompt、Retriever、Tool、Middleware、Agent Loop 等可组合抽象。LangChain 属于这一层的主要候选之一。</p><h3 id="_1-3-工作流运行时" tabindex="-1">1.3 工作流运行时 <a class="header-anchor" href="#_1-3-工作流运行时" aria-label="Permalink to &quot;1.3 工作流运行时&quot;">​</a></h3><p>State、Node、Edge、Checkpoint、Interrupt、Resume 和 Durable Execution。LangGraph 主要解决这一层，不只是“画图工具”。</p><h3 id="_1-4-数据-rag-层" tabindex="-1">1.4 数据/RAG 层 <a class="header-anchor" href="#_1-4-数据-rag-层" aria-label="Permalink to &quot;1.4 数据/RAG 层&quot;">​</a></h3><p>数据连接器、索引、Retriever 和查询引擎。LlamaIndex 等框架在这层提供较完整抽象。</p><h3 id="_1-5-质量与运行平台" tabindex="-1">1.5 质量与运行平台 <a class="header-anchor" href="#_1-5-质量与运行平台" aria-label="Permalink to &quot;1.5 质量与运行平台&quot;">​</a></h3><p>Trace、数据集、评测、部署、版本、权限和运营 UI。可使用独立产品，不必与运行框架绑定。</p><h2 id="_2-约束与标准" tabindex="-1">2. 约束与标准 <a class="header-anchor" href="#_2-约束与标准" aria-label="Permalink to &quot;2. 约束与标准&quot;">​</a></h2><h3 id="_2-1-抽象匹配" tabindex="-1">2.1 抽象匹配 <a class="header-anchor" href="#_2-1-抽象匹配" aria-label="Permalink to &quot;2.1 抽象匹配&quot;">​</a></h3><p>核心任务是简单模型调用、开放 Agent、显式工作流还是数据密集 RAG？若框架主抽象与问题不匹配，团队会不断绕过它。</p><h3 id="_2-2-状态与恢复" tabindex="-1">2.2 状态与恢复 <a class="header-anchor" href="#_2-2-状态与恢复" aria-label="Permalink to &quot;2.2 状态与恢复&quot;">​</a></h3><p>是否需要跨请求/进程恢复、人工中断、状态历史、时间旅行和 Schema 迁移。只保存聊天历史不能替代 Durable Workflow。</p><h3 id="_2-3-可扩展性" tabindex="-1">2.3 可扩展性 <a class="header-anchor" href="#_2-3-可扩展性" aria-label="Permalink to &quot;2.3 可扩展性&quot;">​</a></h3><p>能否替换模型、工具、存储和序列化；是否允许直接调用底层 SDK；自定义点是公开接口还是内部 Patch。</p><h3 id="_2-4-可测试与观测" tabindex="-1">2.4 可测试与观测 <a class="header-anchor" href="#_2-4-可测试与观测" aria-label="Permalink to &quot;2.4 可测试与观测&quot;">​</a></h3><p>是否能注入 Fake、观察模型/工具/节点事件、导出标准 Trace、复现状态并对关键路径做契约测试。</p><h3 id="_2-5-生产与治理" tabindex="-1">2.5 生产与治理 <a class="header-anchor" href="#_2-5-生产与治理" aria-label="Permalink to &quot;2.5 生产与治理&quot;">​</a></h3><p>版本稳定性、迁移政策、安全响应、许可证、维护活跃度、团队技能和托管依赖。</p><h2 id="_3-候选架构" tabindex="-1">3. 候选架构 <a class="header-anchor" href="#_3-候选架构" aria-label="Permalink to &quot;3. 候选架构&quot;">​</a></h2><h3 id="_3-1-直接-sdk-自有代码" tabindex="-1">3.1 直接 SDK + 自有代码 <a class="header-anchor" href="#_3-1-直接-sdk-自有代码" aria-label="Permalink to &quot;3.1 直接 SDK + 自有代码&quot;">​</a></h3><p>适合少量模型调用、工具有限、控制流简单。依赖最少、行为透明；随着状态、恢复和流式事件增加，自建运行时成本迅速上升。</p><h3 id="_3-2-langchain" tabindex="-1">3.2 LangChain <a class="header-anchor" href="#_3-2-langchain" aria-label="Permalink to &quot;3.2 LangChain&quot;">​</a></h3><p>适合统一模型、工具、Agent 和 Middleware 等组件，生态广。仍需理解供应商能力与 Agent 原理，不能把框架封装当成通用保证。</p><h3 id="_3-3-langgraph" tabindex="-1">3.3 LangGraph <a class="header-anchor" href="#_3-3-langgraph" aria-label="Permalink to &quot;3.3 LangGraph&quot;">​</a></h3><p>适合显式有状态图、Checkpoint、Interrupt、循环和长时间执行。简单请求若不需要这些能力，图运行时可能增加不必要复杂度。</p><h3 id="_3-4-llamaindex" tabindex="-1">3.4 LlamaIndex <a class="header-anchor" href="#_3-4-llamaindex" aria-label="Permalink to &quot;3.4 LlamaIndex&quot;">​</a></h3><p>适合文档、索引、Retriever 与数据 Agent 场景。若系统主要是业务工具编排而非数据/RAG，优势可能有限。</p><h3 id="_3-5-托管-agent-平台" tabindex="-1">3.5 托管 Agent 平台 <a class="header-anchor" href="#_3-5-托管-agent-平台" aria-label="Permalink to &quot;3.5 托管 Agent 平台&quot;">​</a></h3><p>可提供运行、观测、部署和管理 UI，减少基础设施工作；代价是数据、运行语义、价格和迁移受平台约束。</p><p>这些候选可以组合，但每增加一层都要明确谁拥有状态、重试、Trace 和版本。</p><h2 id="_4-评分矩阵" tabindex="-1">4. 评分矩阵 <a class="header-anchor" href="#_4-评分矩阵" aria-label="Permalink to &quot;4. 评分矩阵&quot;">​</a></h2><p>下面不是通用排行榜，而是一个填写完成的场景：售后退款流程需要可暂停审批、跨进程恢复、自托管 Checkpoint、OpenTelemetry 导出和境内数据处理；团队已有 Python 服务经验，但不准备自建持久工作流运行时。候选均先通过数据地域和许可证硬约束。</p><p>评分采用 <code>1</code>（明显不满足）到 <code>5</code>（充分满足）。每个数字来自 PoC 中的恢复、升级、观测和负载证据，而不是厂商宣传材料。</p><table tabindex="0"><thead><tr><th>标准</th><th style="text-align:right;">权重</th><th style="text-align:right;">直接 SDK + 自建状态机</th><th style="text-align:right;">LangChain + LangGraph</th><th style="text-align:right;">合规托管 Agent 平台</th></tr></thead><tbody><tr><td>Interrupt 与恢复</td><td style="text-align:right;">20</td><td style="text-align:right;">2</td><td style="text-align:right;">5</td><td style="text-align:right;">4</td></tr><tr><td>工具和模型接入</td><td style="text-align:right;">10</td><td style="text-align:right;">3</td><td style="text-align:right;">5</td><td style="text-align:right;">4</td></tr><tr><td>State 版本与迁移</td><td style="text-align:right;">15</td><td style="text-align:right;">2</td><td style="text-align:right;">4</td><td style="text-align:right;">3</td></tr><tr><td>测试与 Trace 导出</td><td style="text-align:right;">15</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">3</td></tr><tr><td>数据与部署控制</td><td style="text-align:right;">15</td><td style="text-align:right;">5</td><td style="text-align:right;">5</td><td style="text-align:right;">3</td></tr><tr><td>团队学习与实现成本</td><td style="text-align:right;">10</td><td style="text-align:right;">3</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td></tr><tr><td>长期升级与退出</td><td style="text-align:right;">15</td><td style="text-align:right;">5</td><td style="text-align:right;">3</td><td style="text-align:right;">2</td></tr><tr><td>加权总分</td><td style="text-align:right;">100</td><td style="text-align:right;">3.40</td><td style="text-align:right;">4.30</td><td style="text-align:right;">3.25</td></tr></tbody></table><p>结论选择 <code>LangChain + LangGraph</code>，原因是恢复和人工暂停是本场景的核心驱动因素，且 Checkpoint 可保持在自有环境。直接 SDK 保留为简单模型调用适配器；托管平台因退出与数据控制证据不足而暂不采用。负面后果是框架 State、事件和序列化需要版本测试，因此业务契约必须留在内部端口。</p><p>这些数字只对当前场景有效。若任务变成三个无状态模型调用，直接 SDK 的实现与运维成本会明显下降，决策可能反转。</p><h2 id="_5-proof-of-concept" tabindex="-1">5. Proof of Concept <a class="header-anchor" href="#_5-proof-of-concept" aria-label="Permalink to &quot;5. Proof of Concept&quot;">​</a></h2><p>PoC 使用一条代表性高风险旅程，而不是“Hello World”：</p><ol><li>流式模型调用与结构化工具；</li><li>一个写工具的授权与人工 Interrupt；</li><li>进程在节点间故障后恢复；</li><li>状态 Schema 演进；</li><li>模型/工具错误、取消和 Deadline；</li><li>Trace、Token、成本与评测关联；</li><li>替换模型或存储适配器；</li><li>运行目标负载和部署回滚。</li></ol><p>PoC 产物包括代码、Trace、失败记录、学习成本和迁移风险，不只是演示视频。</p><h2 id="_6-框架边界设计" tabindex="-1">6. 框架边界设计 <a class="header-anchor" href="#_6-框架边界设计" aria-label="Permalink to &quot;6. 框架边界设计&quot;">​</a></h2><h3 id="_6-1-内部端口" tabindex="-1">6.1 内部端口 <a class="header-anchor" href="#_6-1-内部端口" aria-label="Permalink to &quot;6.1 内部端口&quot;">​</a></h3><p>业务用例依赖 <code>AgentPort</code>、<code>ToolPort</code>、<code>CheckpointPort</code> 等内部契约；框架对象限制在运行时适配器。避免业务表存储不可理解的框架私有对象。</p><h3 id="_6-2-state-schema" tabindex="-1">6.2 State Schema <a class="header-anchor" href="#_6-2-state-schema" aria-label="Permalink to &quot;6.2 State Schema&quot;">​</a></h3><p>State 使用业务可理解的类型，保存显式版本。框架 Checkpoint 是执行恢复，不成为业务权威记录。</p><h3 id="_6-3-事件适配" tabindex="-1">6.3 事件适配 <a class="header-anchor" href="#_6-3-事件适配" aria-label="Permalink to &quot;6.3 事件适配&quot;">​</a></h3><p>将框架流式事件转换为应用稳定协议，使前端和消费者不直接依赖版本敏感事件名。</p><h3 id="_6-4-trace" tabindex="-1">6.4 Trace <a class="header-anchor" href="#_6-4-trace" aria-label="Permalink to &quot;6.4 Trace&quot;">​</a></h3><p>保留开放标准 Trace 与内部 Run ID；框架专用观测可作为增强，而不是唯一证据出口。</p><h2 id="_7-平台托管边界" tabindex="-1">7. 平台托管边界 <a class="header-anchor" href="#_7-平台托管边界" aria-label="Permalink to &quot;7. 平台托管边界&quot;">​</a></h2><p>评估数据保存与地域、网络连接、身份/RBAC、Secret、审计、模型凭据、配额、导出、备份、SLA 和退出能力。托管减少谁的工作，也转移谁的控制权，必须写清责任矩阵。</p><p>控制面不可用时，运行数据面是继续使用已知配置还是停止；平台能否导出 Run、数据集、Prompt 和 Checkpoint；这些比 UI 功能数量更关键。</p><h2 id="_8-版本与升级" tabindex="-1">8. 版本与升级 <a class="header-anchor" href="#_8-版本与升级" aria-label="Permalink to &quot;8. 版本与升级&quot;">​</a></h2><p>锁定框架版本，关注弃用和迁移指南；用契约测试覆盖 Agent 创建、工具 Schema、State、Checkpoint、流式事件和错误。先在候选分支读取旧状态并运行回归，再升级生产。</p><p>不要依赖私有模块路径或未承诺稳定的序列化。新功能若标记实验性，应隔离并提供回退。</p><h2 id="_9-总拥有成本" tabindex="-1">9. 总拥有成本 <a class="header-anchor" href="#_9-总拥有成本" aria-label="Permalink to &quot;9. 总拥有成本&quot;">​</a></h2><p>计算开发学习、调试、运行、托管费用、升级、迁移、值班和供应商锁定。少写 500 行代码不一定降低长期成本；同样，自建所有能力也未必更可控。</p><p>框架价值应通过交付速度、缺陷、恢复时间和可维护性数据复查，而不是“团队已经使用”成为永久理由。</p><h2 id="_10-决策记录" tabindex="-1">10. 决策记录 <a class="header-anchor" href="#_10-决策记录" aria-label="Permalink to &quot;10. 决策记录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：需要可暂停并跨进程恢复的审批工作流</span></span>
<span class="line"><span>硬约束：Python；自托管 Checkpoint；OpenTelemetry 导出</span></span>
<span class="line"><span>候选：自建状态机、LangGraph、托管平台</span></span>
<span class="line"><span>实验：进程故障恢复、Interrupt、Schema v1-&gt;v2、p95</span></span>
<span class="line"><span>选择：LangGraph + 内部端口 + 自托管 Checkpointer</span></span>
<span class="line"><span>未选择：托管平台因数据地域；自建因恢复成本</span></span>
<span class="line"><span>风险：框架事件与序列化升级</span></span>
<span class="line"><span>缓解：事件适配层、状态迁移测试、版本锁定</span></span>
<span class="line"><span>复查：规模扩大 10 倍或平台合规条件变化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="_11-常见误区" tabindex="-1">11. 常见误区 <a class="header-anchor" href="#_11-常见误区" aria-label="Permalink to &quot;11. 常见误区&quot;">​</a></h2><ol><li><strong>功能最多就是最好</strong>：不匹配的抽象会增加绕行代码。</li><li><strong>框架消除了底层差异</strong>：模型、工具和存储语义仍不同。</li><li><strong>PoC 只跑成功路径</strong>：恢复、升级和取消才暴露平台边界。</li><li><strong>使用开源就没有锁定</strong>：State、事件和序列化也会锁定。</li><li><strong>所有层选同一供应商</strong>：便利性可能扩大故障与迁移半径。</li></ol><p>框架选择不是押注一个品牌，而是为每一层分配责任。先保持业务契约独立，再让框架承担它真正擅长的运行复杂度，团队才有升级和替换空间。</p>`,71)])])}const u=t(l,[["render",i]]);export{g as __pageData,u as default};
